#!/usr/bin/env python3
"""Regenerate an S*/E*.md transcript body from the six friend/* branches."""
import subprocess, sys, datetime, os

REPO = "/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
BRANCHES = {"rachel": "Rachel", "monica": "Monica", "phoebe": "Phoebe",
            "joey": "Joey", "chandler": "Chandler", "ross": "Ross"}


def git(*args):
    return subprocess.run(["git", "-C", REPO] + list(args), capture_output=True,
                          text=True, stdin=subprocess.DEVNULL, check=True).stdout


def commit_msg(sha):
    raw = subprocess.run(["git", "-C", REPO, "cat-file", "commit", sha],
                         capture_output=True, text=True,
                         stdin=subprocess.DEVNULL, check=True).stdout
    return raw.split("\n\n", 1)[1].rstrip("\n")


def cdate(sha):
    out = git("show", "-s", "--format=%cI", sha).strip()
    dt = datetime.datetime.fromisoformat(out)
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def collect(episode):
    rows = []
    for br, name in BRANCHES.items():
        shas = git("log", "--format=%H", "origin/friend/" + br).split()
        for sha in shas:
            msg = commit_msg(sha)
            if "Friend-Message: 1" not in msg:
                continue
            fields = {}
            body = None
            for block in msg.split("\n\n"):
                if block.startswith("Friend-Message:"):
                    for line in block.splitlines():
                        if ": " in line:
                            k, v = line.split(": ", 1)
                            fields[k] = v
                else:
                    body = block
            if fields.get("Episode") != episode:
                continue
            if body is None:
                continue
            rows.append({
                "sha": sha, "branch": br, "speaker": fields.get("Speaker", name),
                "date": cdate(sha), "body": body,
                "reply": fields.get("Reply-To", ""),
            })
    rows.sort(key=lambda r: (r["date"], r["sha"]))
    return rows


def render(rows):
    out = []
    for r in rows:
        out.append("**%s** (%s)\n" % (r["speaker"], r["date"]))
        out.append("Source: friend/%s @ %s\n" % (r["branch"], r["sha"]))
        out.append(r["body"])
    return "\n".join(out)


if __name__ == "__main__":
    ep = sys.argv[1]
    rows = collect(ep)
    sys.stdout.write(render(rows))
    sys.stderr.write("rows=%d\n" % len(rows))

